Item.method_code:
/*
    managed_by_id 必須チェック（サーバー版）
    対象:
      - h4_ApprovalWFGroup: [編集者] は必須入力です
      - h4_AppWFGroupForDATFormat: [管理者] は必須入力です
    想定イベント:
      - onBeforeUpdate
*/

Innovator inn = this.getInnovator();

string itemType = this.getType();
if(itemType != "h4_ApprovalWFGroup" && itemType != "h4_AppWFGroupForDATFormat")
{
    return this;
}

string managedById = this.getProperty("managed_by_id", "");
if(managedById != "")
{
    return this;
}

string label = "編集者";
if(itemType == "h4_AppWFGroupForDATFormat")
{
    label = "管理者";
}

Item userMsgItem = inn.newItem("UserMessage", "get");
userMsgItem.setAttribute("select", "text");
userMsgItem.setProperty("name", "h4_C_I_0702");
userMsgItem = userMsgItem.apply();

string msgTemplate = "[{0}] は必須入力です";
if(!userMsgItem.isError() && userMsgItem.getItemCount() > 0)
{
    msgTemplate = userMsgItem.getProperty("text", msgTemplate);
}

string msg = msgTemplate.Replace("{0}", label);
return inn.newError(msg);
